  // ---- matching helpers: identical rules for every word game -------------------------------------
  var LATIN_MAP = { 'ł': 'l', 'Ł': 'l', 'ø': 'o', 'Ø': 'o', 'đ': 'd', 'ð': 'd', 'ß': 'ss', 'æ': 'ae', 'œ': 'oe' };
  function fold(s) {
    s = String(s == null ? '' : s).toLowerCase();
    var out = '';
    for (var i = 0; i < s.length; i++) out += (LATIN_MAP[s[i]] !== undefined ? LATIN_MAP[s[i]] : s[i]);
    try { out = out.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); } catch (e) {}
    return out;
  }
  // Ukrainian: the game accepts Latin spelling, so a bank must be unique AFTER this too.
  var CYR = { 'а': 'a', 'б': 'b', 'в': 'v', 'г': 'h', 'ґ': 'g', 'д': 'd', 'е': 'e', 'є': 'ye', 'ж': 'zh',
    'з': 'z', 'и': 'y', 'і': 'i', 'ї': 'yi', 'й': 'y', 'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n', 'о': 'o',
    'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f', 'х': 'kh', 'ц': 'ts', 'ч': 'ch', 'ш': 'sh',
    'щ': 'shch', 'ь': '', 'ю': 'yu', 'я': 'ya' };
  function translit(s) {
    s = String(s == null ? '' : s).toLowerCase();
    var out = '';
    for (var i = 0; i < s.length; i++) out += (CYR[s[i]] !== undefined ? CYR[s[i]] : s[i]);
    return out;
  }

  var _bands = {};
  function bands(locale) {
    var list = BANKS[locale] || BANKS.en;
    if (_bands[locale]) return _bands[locale];
    var sorted = list.slice().sort(function (a, b) { return a.length - b.length || (a < b ? -1 : 1); });
    var t = Math.floor(sorted.length / 3);
    var out = { short: sorted.slice(0, t), medium: sorted.slice(t, t * 2), long: sorted.slice(t * 2) };
    _bands[locale] = out;
    return out;
  }
  function byLength(locale, min, max) {
    var list = BANKS[locale] || BANKS.en;
    return list.filter(function (w) { return w.length >= (min || 0) && w.length <= (max || 99); });
  }

  window.KOMYO_WORDS = { banks: BANKS, fold: fold, translit: translit, bands: bands, byLength: byLength,
    locales: Object.keys(BANKS) };
